p { color: #111; }
.boton { padding: 8px; }
#logo { width: 120px; }
h1, h2 { font-weight: 800; }

p {
  font-family: "DM Sans", sans-serif;
  font-size: 1.125rem;
  line-height: 1.6;
}

p { color: black; }
.nota { color: blue; }
/* <p class="nota"> será azul */

.padre { position: relative; }
.sello {
  position: absolute;
  top: 8px; right: 8px;
}

.barra {
  display: flex; gap: 12px;
  justify-content: space-between;
  align-items: center;
}

.binder {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px;
}
